$checks=0;
function bp_expect(bool $ok,string $label): void {global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;}
function bp_unit(int $id,int $speed=100): array {return ['id'=>$id,'name'=>'Partner '.$id,'slug'=>'agumon','level'=>20,'stage'=>'Rookie','sprite'=>'images/digimon/agumon.png','hp'=>1000,'max_hp'=>1000,'sp'=>500,'max_sp'=>500,'atk'=>100,'def'=>100,'int'=>100,'spd'=>$speed,'attribute'=>'Free','element'=>'Neutral','effects'=>[],'moves'=>dn_moves_catalog()];}
function bp_state(): array {$s=dn_team_create([bp_unit(1,900),bp_unit(2,800),bp_unit(3,700),bp_unit(4,600)],[bp_unit(10,300),bp_unit(11,200),bp_unit(12,100)]);dn_team_next($s);return $s;}
function bp_events(array $events,string $type): array {return array_values(array_filter($events,fn($e)=>$e['type']===$type));}
function bp_turn(array &$s,array $command): array {
    $initial=dn_team_presentation_snapshot($s);dn_team_presentation_begin($s);dn_team_take_turn($s,$command);$visual=dn_team_presentation_end($s);$replay=$initial;
    foreach($visual['events'] as $event){
        foreach($event['units'] as $key=>$patch){$side=str_starts_with($key,'l')?'left':'right';$replay[$side][$key]=array_replace($replay[$side][$key],$patch);}
        foreach(['active_left','active_right','finished','result','round'] as $field)if(array_key_exists($field,$event))$replay[$field]=$event[$field];
    }
    bp_expect($replay===dn_team_presentation_snapshot($s),'event patches reconcile exactly to authoritative final state');
    bp_expect(!isset($s['_presentation'])&&!isset($s['presentation']),'collector is removed from battle state');
    return $visual['events'];
}
